/* ActionButtonMergeInventorySubmit */
$components.FormMergeInventory.data.(
  $mergeAll := $exists(mergeAll) ? mergeAll : false;
  {
    "sourceInventoryId": sourceInventory.id,
    "destinationInventoryId": destinationInventory.id,
    "mergeQty": $not($mergeAll) ? {
      "value": mergeQty,
      "unitId": mergeQtyUnits.id
    },
    "mergeAll": $mergeAll ? mergeAll
  }
)

props.onChange:
$isNilOrEmpty(newValue)
  ? {"sourceInventory": null}
  : (
    $sourceInventory := $query({
      "statement":'
        query Inventory($whereSource: InventoryWhereInput) {
          sourceInventory: inventory(where: $whereSource) {
            edges {
              node {
                id
                active
                serialNumber
                quantity {
                  value
                  unitId
                  unit {
                    id
                    code
                    unitTypeId
                  }
                }
                shippable
                barcode
                trackingNumber
                note
                grossWeight {
                  value
                  unitId
                  unit {
                    code
                  }
                }
                netWeight {
                  value
                  unitId
                  unit {
                    code
                  }
                }
                expiresAt
                lastCountAt
                manufacturedAt
                workOrderId
                externalId
                extProductId
                extProcessId
                customData
                integrationData
                handlingUnitId
                inventoryStatusId
                storageUnitId
                lotId
                processId
                productId
                receiptLineId

              }
            }
          }
        }
      ',
      "variables":{
        "whereSource": {
          "_or": [
            {"serialNumber": {"_eq": newValue}},
            {"barcode": {"_eq": newValue}}
          ]
        }
      }}
    ).sourceInventory.edges.node;

    $components.FormMergeInventory.fn.focus("destinationInventoryBarcode");

    {
      "sourceInventory": $sourceInventory
    }
  )

$isNilOrEmpty(newValue)
  ? {"destinationInventory": null}
  : (
    $destinationInventory := $query({
      "statement":'
        query Inventory($whereDestination: InventoryWhereInput) {
          destinationInventory: inventory(where: $whereDestination) {
            edges {
              node {
                id
                active
                serialNumber
                quantity {
                  value
                  unitId
                  unit {
                    id
                    code
                    unitTypeId
                  }
                }
                shippable
                barcode
                trackingNumber
                note
                grossWeight {
                  value
                  unitId
                  unit {
                    code
                  }
                }
                netWeight {
                  value
                  unitId
                  unit {
                    code
                  }
                }
                expiresAt
                lastCountAt
                manufacturedAt
                workOrderId
                externalId
                extProductId
                extProcessId
                customData
                integrationData
                handlingUnitId
                inventoryStatusId
                storageUnitId
                lotId
                processId
                productId
                receiptLineId
              }
            }
          }
        }
      ',
      "variables":{
        "whereDestination": {
          "_or": [
            {"serialNumber": {"_eq": newValue}},
            {"barcode": {"_eq": newValue}}
          ]
        }
      }}
    ).destinationInventory.edges.node;

    $components.FormMergeInventory.fn.focus("mergeQty");

    {"destinationInventory": $destinationInventory}
  )

